def form(n, title, desc):
    fields = f'<label>Nombre<input name="nombre" autocomplete="name" required placeholder="Tu nombre"></label><label>Celular<input name="telefono" type="tel" autocomplete="tel" required pattern="[+0-9 ()-]{{10,20}}" placeholder="{PHONE_FORMATTED}"></label>'
    options = ['Conocer precios', 'Revisar opciones de financiamiento', 'Conocer el Parque Acuático', 'Agendar una visita'] if n == 1 else ['Casa de campo', 'Granja', 'Inversión', 'Recreación familiar'] if n == 2 else ['Precios', 'Planes de pago', 'Disponibilidad de lotes', 'Visita al Parque Acuático']
    if n == 3:
        fields += '<label>Correo electrónico<input type="email" name="correo" autocomplete="email" required placeholder="tu@correo.com"></label>'
    fields += '<label>' + ('¿Para qué quieres tu lote?' if n == 2 else '¿Qué deseas conocer?') + '<select name="interes">' + ''.join(f'<option>{o}</option>' for o in options) + '</select></label>'
    if n == 2:
        fields += '<label>¿Te gustaría conocer el Parque Acuático?<select name="visita"><option>Sí, quiero agendar una visita</option><option>Primero quiero recibir información</option></select></label>'
    if n == 3:
        fields += '<label class="full">Mensaje opcional<textarea name="mensaje" rows="3" placeholder="Cuéntanos qué estás buscando"></textarea></label>'
    return f'<section class="contact section" id="{["informacion","opciones","cotizar"][n-1]}"><div>{label("HABLEMOS DE TU PRÓXIMO PROYECTO")}<h2>{title}</h2><p>{desc}</p><div class="contact-note">Lotes desde <strong>750 m²</strong><br>Crédito personalizado · Sin revisión de buró</div></div><form>{fields}<button class="button full" type="submit">{["Quiero recibir información","Quiero conocer mis opciones","Solicitar mi cotización"][n-1]} <span>↗</span></button><p class="fine full">Vista previa: los datos no se envían todavía. Tus datos se utilizarán únicamente para brindarte información de Granjas Diversión.</p><p class="form-status full" role="status"></p></form></section>'

